@php($prefix=$next?'next_':'')
<div class="grid gap-4 md:grid-cols-2" x-data="{
    vendor: @js((string)old($prefix.'vendor_party_role_id',$values[$prefix.'vendor_party_role_id']??'')),
    capability: @js((string)old($prefix.'vendor_service_id',$values[$prefix.'vendor_service_id']??'')),
    rate: @js((string)old($prefix.'agreed_unit_rate_pkr',$values[$prefix.'agreed_unit_rate_pkr']??'')),
    location: @js((string)old($prefix.'contractor_location_id',$values[$prefix.'contractor_location_id']??'')),
    choices: @js($capabilities->map(fn($c)=>['id'=>(string)$c->id,'vendor'=>(string)$c->vendor_party_role_id,'unit'=>$c->processingService->billingUnit->code,'rates'=>$c->rates->map(fn($r)=>['from'=>$r->effective_from->format('Y-m-d'),'to'=>$r->effective_to?->format('Y-m-d'),'rate'=>$r->unit_rate])])->values()),
    unit(){return this.choices.find(c=>c.id===this.capability)?.unit??''},
    fillRate(){const c=this.choices.find(c=>c.id===this.capability);const r=c?.rates.find(r=>r.from<=date&&(!r.to||r.to>date));this.rate=r?.rate??'';}
}" x-init="$watch('date', () => fillRate())">
<label class="text-sm">{{ $next?'Next vendor':'Vendor' }}<select required name="{{ $prefix }}vendor_party_role_id" x-model="vendor" @change="capability='';rate='';location=''" class="mt-1 block w-full rounded-lg border border-line px-3 py-2"><option value="">Select vendor</option>@foreach($vendors as $vendor)<option value="{{ $vendor->id }}">{{ $vendor->party->legal_name }}</option>@endforeach</select></label>
<label class="text-sm">Service<select required name="{{ $prefix }}vendor_service_id" x-model="capability" @change="fillRate()" class="mt-1 block w-full rounded-lg border border-line px-3 py-2"><option value="">Select service</option>@foreach($capabilities as $c)<option value="{{ $c->id }}" x-show="vendor==='{{ $c->vendor_party_role_id }}'" :disabled="vendor!=='{{ $c->vendor_party_role_id }}'">{{ $c->processingService->name }} / {{ $c->processingService->billingUnit->code }}</option>@endforeach</select></label>
<label class="text-sm">Agreed PKR rate / <span x-text="unit()"></span><input type="number" step="0.00000001" min="0" name="{{ $prefix }}agreed_unit_rate_pkr" x-model="rate" class="mt-1 block w-full rounded-lg border border-line px-3 py-2"><span class="text-xs text-slate-500">Published rate fills for the selected date. Blank uses the published rate.</span></label>
<label class="text-sm">Vendor location (optional)<select name="{{ $prefix }}contractor_location_id" x-model="location" class="mt-1 block w-full rounded-lg border border-line px-3 py-2"><option value="">Create automatically from vendor name</option>@foreach($locations->where('location_type','contractor') as $location)<option value="{{ $location->id }}" x-show="vendor==='{{ $location->contractor_vendor_party_role_id }}'" :disabled="vendor!=='{{ $location->contractor_vendor_party_role_id }}'">{{ $location->warehouse->name }} / {{ $location->name }}</option>@endforeach</select><span class="text-xs text-slate-500">If no location is selected, the system creates or reuses one vendor custody location automatically.</span></label>
<details class="md:col-span-2"><summary class="cursor-pointer text-sm text-slate-500">Rate change reason and loss allowance (optional)</summary><div class="mt-3 grid gap-4 md:grid-cols-2"><label class="text-sm">Reason if changing the published rate<input name="{{ $prefix }}override_reason" value="{{ old($prefix.'override_reason',$values[$prefix.'override_reason']??'') }}" maxlength="500" class="mt-1 block w-full rounded-lg border border-line px-3 py-2"></label>
<label class="text-sm">Allowed normal loss %<input type="number" min="0" max="99.999999" step="0.000001" name="{{ $prefix }}normal_loss_percent" value="{{ old($prefix.'normal_loss_percent',$values[$prefix.'normal_loss_percent']??'0') }}" class="mt-1 block w-full rounded-lg border border-line px-3 py-2"></label>
</div></details>
</div>
